  if (preserve) {
    return done(
      fs.mkdirSync(dir, { mode, recursive: true }) ?? undefined,
    )
  }

  const sub = normalizeWindowsPath(path.relative(cwd, dir))
  const parts = sub.split('/')
  let created: string | undefined = undefined
  for (
    let p = parts.shift(), part = cwd;
    p && (part += '/' + p);
    p = parts.shift()
