  cache.add(s)

  const ret = normalizeCache[s] as string

  let i = cache.size - MAX
  // only prune when we're 10% over the max
  if (i > MAX / 10) {
    for (const s of cache) {
      cache.delete(s)
      delete normalizeCache[s]
      if (--i <= 0) break
    }
  }

  return ret
}
